using FlexExtractor;
using System.Text.Json;
static partial class Cases {
 public static void TestStationMatchLegacyRules(){foreach(var t in new[]{"31","0031","0031_1_1","*","all","ALL"})Program.Check(Scanner.Matches("0031_1_1",t),"legacy rule failed "+t);Program.Check(!Scanner.Matches("00310_1","31")&&!Scanner.Matches("0041_1","31"),"station match leaked");}
 public static void TestSharedSaveFolderAcrossRoles(){var c=Cfg(Fresh());c.BindItems=[new(){Token="31",StationName="组装",SaveFolder=c.DispenseItems[0].SaveFolder}];Source(c);var r=(ScanResult)Scan(c);Program.Check(r.Copied==1&&r.Skipped==1,"shared folder duplicate work");}
 public static void TestSameLengthSameMtimeChangedSourceUsesContentHash(){var c=Cfg(Fresh());var source=Source(c,text:"<root>1111111111</root>");var stamp=File.GetLastWriteTimeUtc(source);Scan(c);File.WriteAllText(source,"<root>2222222222</root>");File.SetLastWriteTimeUtc(source,stamp);Scan(c);Program.Check(Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Length==2,"same-length same-mtime source mutation lost");}
 public static void TestLockedSourceRetryRecovers(){var c=Cfg(Fresh());var s=Source(c);using(var locked=new FileStream(s,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){var r=(ScanResult)Scan(c);Program.Check(r.Failed>0,"locked source invisible");}var later=(ScanResult)Scan(c);Program.Check(later.Copied==1,"locked source not retried");}
 public static void TestModifiedOwnedFileNeverDeleted(){var c=Cfg(Fresh());Source(c);Scan(c);var folder=c.DispenseItems[0].SaveFolder;var dest=Directory.GetFiles(folder,"Request*.xml").Single();File.WriteAllText(dest,"<modified/>");var result=new ScanResult();Ownership.Purge(folder,1,DateTime.UtcNow.AddDays(3),result);Program.Check(File.Exists(dest)&&result.Failed>0,"modified owned file deleted or warning absent");}
 public static void TestCorruptOwnershipFailsClosed(){var c=Cfg(Fresh());Source(c);Scan(c);var folder=c.DispenseItems[0].SaveFolder;File.WriteAllText(Path.Combine(folder,Ownership.Manifest),"{broken");Rejected(()=>Ownership.Purge(folder,1,DateTime.UtcNow.AddDays(3),new()));Program.Check(Directory.GetFiles(folder,"Request*.xml").Length==1,"bad manifest caused deletion");}
 public static void TestDtdRejected(){var c=Cfg(Fresh());Source(c,text:"<!DOCTYPE root [<!ENTITY x SYSTEM 'file:///C:/Windows/win.ini'>]><root>&x;</root>");var r=(ScanResult)Scan(c);Program.Check(r.Failed>0&&Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Length==0,"DTD accepted");}
 public static void TestConfigAtomicRejectInvalidPreservesPrevious(){var c=Cfg(Fresh());var path=Path.Combine(Path.GetDirectoryName(c.WatchRoot)!,"config.json");Durable.SaveConfig(path,c);var old=File.ReadAllBytes(path);c.KeepDays=0;Rejected(()=>Durable.SaveConfig(path,c));Program.Check(File.ReadAllBytes(path).SequenceEqual(old),"invalid config replaced valid file");Rejected(()=>Config.Parse("{\"WatchRoot\":\"A\",\"watchroot\":\"B\"}"));Rejected(()=>Config.Parse("{\"LookbackDays\":2,}"));}
 public static void TestExpiredSourceNotCopied(){var c=Cfg(Fresh());var source=Source(c);File.SetCreationTimeUtc(source,DateTime.UtcNow.AddDays(-5));File.SetLastWriteTimeUtc(source,DateTime.UtcNow.AddDays(-5));var r=(ScanResult)Scan(c);Program.Check(r.Copied==0&&r.Skipped==1,"expired source copied");}
 public static void TestOldCreationRecentWriteIsKept(){var c=Cfg(Fresh());var source=Source(c);File.SetCreationTimeUtc(source,DateTime.UtcNow.AddDays(-5));Scan(c);Program.Check(Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Length==1,"retention did not use newer timestamp");}
 public static void TestOversizeFileRejected(){var c=Cfg(Fresh());c.MaxFileBytes=32;Source(c,text:"<root>"+new string('a',100)+"</root>");var r=(ScanResult)Scan(c);Program.Check(r.Failed>0&&Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Length==0,"oversized source published");}
}
